# Triagem por regras. Lê os cabeçalhos do Gmail (nomes em minúsculas) e o endereço de quem enviou.
# sinal 'forte' = ignorar. 'provavel' = seguir para o Telegram com aviso. 'nenhum' = e-mail de pessoa.
PREFIXOS_FORTES = ('noreply', 'donotreply', 'mailerdaemon', 'postmaster')
PREFIXOS_PROVAVEIS = ('notification', 'notificacao', 'notificacoes', 'alert', 'automated', 'automatico', 'bounce', 'system', 'sistema', 'mailer')
ASSUNTOS_PROVAVEIS = ('resposta automática', 'resposta automatica', 'fora do escritório', 'fora do escritorio', 'out of office', 'automatic reply', 'autoreply', 'código de verificação', 'codigo de verificacao', 'verification code', 'delivery status notification', 'undeliverable', 'fatura')
CORPOS_PROVAVEIS = ('não responda este e-mail', 'nao responda este e-mail', 'não responda a este e-mail', 'nao responda a este e-mail', 'do not reply to this email', 'do not reply to this e-mail', 'this is an automated')


def cab(h, nome):
    valor = h.get(nome, '')
    if isinstance(valor, list):
        valor = ' '.join(str(v) for v in valor)
    valor = str(valor).strip()
    # O Gmail devolve o valor com o nome na frente (ex.: 'Precedence: bulk'). Tira o prefixo.
    if valor.lower().startswith(nome + ':'):
        valor = valor[len(nome) + 1:]
    return valor.strip().lower()


saida = []
for item in _items:
    msg = item['json']
    h = msg.get('headers') or {}
    de = (((msg.get('from') or {}).get('value')) or [{}])[0]
    remetente = str(de.get('address', '')).lower()
    meus = [e.strip().lower() for e in str(msg.get('meusEmails', '')).split(',') if e.strip()]
    local = remetente.split('@')[0].replace('-', '').replace('_', '').replace('.', '')
    assunto = msg.get('subject') or ''
    corpo = (msg.get('text') or '').lower()[:3000]
    rotulos = msg.get('labelIds') or []

    fortes = []
    auto = cab(h, 'auto-submitted')
    if auto and auto != 'no':
        fortes.append('cabeçalho Auto-Submitted: ' + auto)
    if cab(h, 'precedence') in ('bulk', 'list', 'junk'):
        fortes.append('cabeçalho Precedence: ' + cab(h, 'precedence'))
    if 'list-unsubscribe' in h or 'list-id' in h:
        fortes.append('lista de e-mail (List-Unsubscribe ou List-Id)')
    if 'x-auto-response-suppress' in h:
        fortes.append('cabeçalho X-Auto-Response-Suppress')
    if 'multipart/report' in cab(h, 'content-type'):
        fortes.append('relatório de entrega (multipart/report)')
    if cab(h, 'return-path') == '<>':
        fortes.append('Return-Path vazio (e-mail devolvido)')
    if remetente and remetente in meus:
        fortes.append('o remetente é você')
    if local.startswith(PREFIXOS_FORTES):
        fortes.append('endereço de remetente automático: ' + remetente)

    provaveis = []
    if local.startswith(PREFIXOS_PROVAVEIS):
        provaveis.append('endereço de notificação: ' + remetente)
    if 'CATEGORY_UPDATES' in rotulos:
        provaveis.append('categoria Atualizações do Gmail')
    if any(t in assunto.lower() for t in ASSUNTOS_PROVAVEIS):
        provaveis.append('assunto típico de e-mail automático')
    if any(t in corpo for t in CORPOS_PROVAVEIS):
        provaveis.append('texto pede para não responder')

    motivos = fortes + provaveis
    saida.append({'json': {
        'id': msg.get('id'),
        'threadId': msg.get('threadId'),
        'remetente': remetente,
        'nomeRemetente': de.get('name', ''),
        'assunto': assunto,
        'sinal': 'forte' if fortes else ('provavel' if provaveis else 'nenhum'),
        'motivos': motivos,
        'motivo': '; '.join(motivos),
    }})

return saida
